    // 置き場所は品ごとの繰り返しをやめ、材料一覧の見出しの下に1回だけ出す。
    // 文は「左に同じ線が付いた材料は」の入れ子をほどき、
    //   ①線が同じもの同士が1組であること ②その組が何なのか ③何ができるのか
    // を短い2文に分けた
    seasoningGroupHint: '左の線が同じ材料どうしは、合わせ調味料です。先にまとめて計量できます',
    openRecipe: 'レシピを開く',
    startTimer: 'タイマーを始める',
    // 待ちのブロックでタイマーが動いている間の表示（2026-08-12 便FS-5・利用者テスト
    // 「タイマーが動いていても、手順の中のボタンが『タイマーを始める』のまま。
    // もう一度押しても何も起きない」）。同じ手順・同じ長さのタイマーは二重に立たないので、
    // 押せるボタンを残すと「押しても何も起きない」ことになる。ボタンを残り時間に置き換え、
    // 動いていること（止めてあること）と、あと何分かを同じ場所で読めるようにする
    waitTimerRunning: 'タイマー動作中 残り{time}',
    waitTimerPaused: 'タイマー一時停止中 残り{time}',
    // 段取りに組んだ品をまとめて記録する(2026-08-08 便ED・オーナー実機フィードバック⑨)。
