    markAllCooked: 'まとめて作った！',
    // 2026-08-14 便GF・利用者テスト「ダイアログに『記録した3件は今日の献立から外れます
    // （レシピと段取りはそのまま残ります）』と書かれているのに、記録をつけると並行調理ナビが
