    // 画面の名前で場所を言う（規約H。「あとで直せます」だけだと、どこで直すのか分からない）
    markAllCookedConfirmEdit: 'つけた記録は、あとから「作った記録の一覧」で1件ずつ編集できます。\n\n',
    markAllCookedConfirmOk: '記録をつける',
    // 調理中モードの最後の手順「完成！」から出す窓の見出し(2026-08-11 便FO・
