    // なぜ確認が出たのかを先に書く。続きは markAllCookedConfirm と同じ文（記録の中身は1か所で持つ）
    sessionFinishTitle: '段取りの最後の手順まで進みました',
    // 「完成！」の窓の3つの行き先（2026-08-12 便FX・オーナー指摘「完成！を押した後の
