    sessionFinishBack: '調理を続ける',
    // 閉じても段取り・調理中の手順は残る（✕と同じ）。記録だけを見送る道
    sessionFinishClose: '記録をつけずに閉じる',
    // 窓の説明を畳む（2026-08-25 便KM・オーナー原文「完成押下後の窓の説明も長い。
    // 読みたい人だけ読めるように、折りたたんでしまうか、さらに別の窓で表示のにしたい。」）。
    // 畳まずに出すのは「どの品に記録が付くか」だけ＝押す前に要る情報。
    // 消えるもの・残るもの・あとから編集できることは、読みたい人だけが開く
