    sessionFinishDetailOpen: '記録の詳しい説明を見る',
    sessionFinishDetailClose: '記録の詳しい説明を閉じる',
    // 調理を終えるときに、動いているタイマーをどうするか聞く（2026-08-14 便GL・利用者テスト
    //   「『動いているタイマーはそのまま残ります』とは書いてあるけど、片づけ中に鳴ります。
