    // 既定は**消さない**（今までの動きを勝手に変えない・押し間違いで残り時間を失わない）。
    // 選んだ結果どうなるかは、消す側・消さない側の両方を書く（規約F）
    sessionFinishTimersTitle: '動いているタイマー{n}件',
    sessionFinishTimersStop: 'このタイマーも消して終わる',
    sessionFinishTimersStopNote: '消すと、残り時間はなくなります。',
    sessionFinishTimersKeepNote: '消さないと、片づけの間も鳴ります。',
    markAllCookedToast: '{n}件の作った記録をつけました',
    markAllCookedUndone: '{n}件の作った記録を取り消して、今日の献立に戻しました',
    markAllCookedUndoNothing: '取り消せる記録が見つかりませんでした（記録はそのままです）',

