    // {n} には画面のバッジと同じ「⑦3-1」（段取りの丸数字＋レシピ内の手順番号）が入る
    sessionResume: '調理中モードの続きから見る',
    sessionResumeHint: '前に開いていた手順{n}から始まります。',
