    // 動きの言い方も「移る」から「先にする」へそろえた（同 オーナー指摘・sessionPeekMove 参照）
    sessionMicColorHint: '、「青」「緑」「ピンク」と言うとその色の品の手順を先にする',
    // 先にできたときの手応え。色の言葉だけでは、どの料理が開いたのか分からないので名前で言う
    sessionColorMoved: '{title}の手順を先にしました',
    // 手順を移すと段取りの通し番号が振り直されることの説明（2026-08-12 便FS-8・利用者テスト
